#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int n, q;
    long long values[2000], difference[2001] = {0};
    scanf("%d%d", &n, &q);
    for (int i = 0; i < n; ++i) {
        scanf("%lld", &values[i]);
    }
    for (int i = 0; i < q; ++i) {
        int left, right;
        long long change;
        scanf("%d%d%lld", &left, &right, &change);
        difference[left - 1] += change;
        difference[right] -= change;
    }
    long long added = 0;
    for (int i = 0; i < n; ++i) {
        added += difference[i];
        printf("%s%lld", i > 0 ? " " : "", values[i] + added);
    }
    printf("\n");
    return 0;
}

